code_templates.solution_code:
#include <iostream>
#include <string>
using namespace std;

void add(int a, int b) {
    cout<<a+b<<endl;
}
void add(double a, double b) {
    cout<<a+b<<endl;
}

int main() {
    add(5,6);
    add(1.2, 6.5);
    
    return 0;
}
